<?php
$identityDocuments = array_values(array_filter($identityDocuments ?? [], static function ($document) { return trim((string) ($document['file_path'] ?? '')) !== ''; }));
$customerFiles = array_values($customerFiles ?? []);
?>
<section class="card"><div class="card-header"><div><h2>مدارک مشتری</h2><p class="text-muted">نمایش و دریافت از مسیرهای امن دارای کنترل دسترسی</p></div></div><div class="card-body">
  <?php if ($identityDocuments): ?><h3>مدارک هویتی</h3><div class="proma-customer-360__document-grid"><?php foreach ($identityDocuments as $document): $url = url('customers/identityDocument/' . (int) $document['id']); ?><article><small><?= e(IdentityDocument::typeLabel($document['document_type'] ?? '')) ?></small><strong><?= e(status_label($document['status'] ?? '')) ?></strong><span><?= !empty($document['uploaded_at']) ? e(jdatetime($document['uploaded_at'])) : 'تاریخ نامشخص' ?></span><div class="actions"><a class="btn small" target="_blank" rel="noopener" href="<?= e($url) ?>">مشاهده</a><a class="btn small secondary" href="<?= e(url('customers/identityDocument/' . (int) $document['id'], ['download' => 1])) ?>">دانلود</a></div></article><?php endforeach; ?></div><?php endif; ?>
  <?php if ($customerFiles): ?><h3 class="mt-3">فایل‌های مشتری و قراردادها</h3><div class="proma-customer-360__document-grid"><?php foreach ($customerFiles as $file): $viewUrl = url('file-manager/view/' . (string) $file['file_uuid']); $downloadUrl = url('file-manager/download/' . (string) $file['file_uuid']); ?><article><small><?= e($file['category'] ?? 'مدرک') ?></small><strong><?= e($file['display_name'] ?: $file['original_name']) ?></strong><span><?= !empty($file['uploader_name']) ? 'بارگذاری توسط ' . e($file['uploader_name']) : 'بارگذار نامشخص' ?> · <?= !empty($file['created_at']) ? e(jdatetime($file['created_at'])) : '' ?></span><div class="actions"><a class="btn small" target="_blank" rel="noopener" href="<?= e($viewUrl) ?>">مشاهده</a><a class="btn small secondary" href="<?= e($downloadUrl) ?>">دانلود</a></div></article><?php endforeach; ?></div><?php endif; ?>
  <?php if (!$identityDocuments && !$customerFiles): ?><div class="proma-empty-state"><h3>مدرکی ثبت نشده است</h3><p>پس از بارگذاری، مدارک در همین بخش در دسترس خواهند بود.</p></div><?php endif; ?>
</div></section>
